export const sendDataToAction = (type: string, data?: any, target?: number) => {
  const ChatRoomMessage: PluginServerChatRoomMessage = {
    Type: "Hidden",
    Content: `${ModIdentifier}Msg`,
    Sender: Player.MemberNumber,
    Target: target,
    Dictionary: [
      {
        type: type,
        data: data,
      },
    ],
  };
  ServerSend("ChatRoomChat", ChatRoomMessage as ServerChatRoomMessage);
};

document.addEventListener("unload", () => {
  syncData.flush();
});
/**
 * Sends an update of the player's settings to the specified target or to everyone in the chat room.
 * use {@link syncData}
 * @param {number} [target] - The MemberNumber of the target player. If not specified, the update is sent to all players.
 */
export const sendUpdateMyData = (target?: number) => {
  if (typeof target === "undefined") {
    settingsRemote.emitAll("sync", {
      Settings: Player.ABCL.Settings,
      SettingPermissions: Player.ABCL.SettingPermissions,
      Stats: Player.ABCL.Stats,
      Version: ModVersion,
    });
  } else {
    settingsRemote.emit(target, "sync", {
      Settings: Player.ABCL.Settings,
      SettingPermissions: Player.ABCL.SettingPermissions,
      Stats: Player.ABCL.Stats,
      Version: ModVersion,
    });
  }
  logger.debug({
    message: `Sending updated data to ${target ?? "everyone"}`,
  });
};

/**
 * Sends a request packet to other players in the chat room to retrieve their data.
 */
export const sendRequestOtherDataPacket = () => {
  settingsRemote.emitAll("init");

  logger.debug(`Requesting data from others.`);
};

/**
 * Processes incoming packets and delegates them to the appropriate handler based on their type.
 *
 * @param {PluginServerChatRoomMessage} receivedMessage - The message data received from the server.
 */

const receivePacket = (receivedMessage: PluginServerChatRoomMessage) => {
  if (receivedMessage?.Content !== `${modIdentifier}Msg`) return;
  if (!receivedMessage.Sender || !receivedMessage.Dictionary) return;
  if (receivedMessage.Sender === Player.MemberNumber) return;
  if (receivedMessage.Type !== "Hidden") return;
  if (!receivedMessage.Dictionary[0]?.type) return;

  const type = receivedMessage.Dictionary[0]?.type as keyof ListenerTypeMap;
  const data = receivedMessage.Dictionary[0]?.data as ListenerTypeMap[typeof type];
  for (const action of actions) {
    const listener = action.listeners?.[type];

    if (listener) {
      (listener as HookListener<ListenerTypeMap[typeof type]>)(receivedMessage, data);
    }
  }
};

/**
 *
 * Initializes hooks for intercepting chat room messages and synchronizing player data.
 * This function waits until the server is connected before setting up hooks.
 */
const activityReplacements: Record<string, string> = {};
export let LSCG_ABCLModApi: types.LSCGModApi;
export const nameTransformationCache = new Map<string, string>();
const initHooks = async () => {
  CommonFetch(publicURL + "/activities.csv").then(async response => {
    if (response.status !== 200) return;
    const text = await response.text();
    const parsed = CommonParseCSV(text);
    parsed.forEach(row => {
      if (!row[0] || !row[1]) return;
      activityReplacements[row[0]] = row[1];
    });
  });

  (window.LSCG_OnLoad = window.LSCG_OnLoad || []).push(LSCG => {
    const api = LSCG.getModApi({ id: "abcl", name: "ABCL", version: "1.0.0" });
    LSCG_ABCLModApi = api;
    api.spells.registerEffect({
      name: "blort-spell",
      label: "Blort Spell",
      description: "Makes the target mess.",
      apply(context) {
        abclPlayer.stats.BowelFullness = 1;
        abclPlayer.soil(false);
      },
    });
    api.spells.registerEffect({
      name: "tinkle-spell",
      label: "Tinkle Spell",
      description: "Makes the target pee.",
      apply(context) {
        abclPlayer.stats.BladderFullness = 1;
        abclPlayer.wet(false);
      },
    });
    api.spells.registerEffect({
      name: "diaper-change",
      label: "Diaper Change Spell",
      description: "Makes the target get changed, if not padded, they will be now.",
      apply(context) {
        if (!hasDiaper(Player)) {
          context.sendAction(grammar.flatten("#changeDiaper-default-magic-unpadded#"));
          applyRandomDiaper(Player, false);
          return;
        }
        abclPlayer.changeDiaper(Player, true);
        context.sendAction(grammar.flatten("#changeDiaper-default-magic#"));
      },
    });
  });

  await waitFor(() => ServerSocket && ServerIsConnected);

  HookManager.hookFunction("ServerSend", 1, (args, next) => {
    let data = args[1] as ServerChatRoomMessage;
    if (args[0] !== "ChatRoomChat" || data?.Type !== "Activity") return next(args);

    let { metadata, substitutions } = ChatRoomMessageRunExtractors(data, Player);
    const activity = metadata?.ActivityName;
    if (activity == null) return next(args);
    if (!activityNames.includes(activity)) return next(args);

    let msg = ActivityDictionaryText(data.Content);
    msg = CommonStringSubstitute(msg, substitutions ?? []);
    data.Dictionary?.push({
      Tag: `${TEXT_NOT_FOUND_PREFIX} "ActivityDictionary.csv": ${data.Content}`,
      Text: msg,
    });
    return next(args);
  });
  HookManager.hookFunction("TextPrefetchFile", 1, (args, next) => {
    if (args[0] !== "Screens/Room/Crafting/Text_Crafting.csv") {
      return next(args);
    }
    const cache = next(args);
    cache.cache["PropertyLaxative"] = "Laxative-laced";
    cache.cache["PropertyDiuretic"] = "Diuretic-laced";
    cache.cache["DescriptionLaxative"] = "Relaxes the wearers bowels";
    cache.cache["DescriptionDiuretic"] = "Numbs the wearers bladder";
    cache.cache["PropertyHollow"] = "Hollow";
    cache.cache["DescriptionHollow"] = "Makes the item hollow inside";
    cache.cache["PropertyDiaperDiscolorationProtection"] = "Discoloration Protection";
    cache.cache["DescriptionDiaperDiscolorationProtection"] = "Prevents the diaper from discoloring";
    cache.cache["PropertyCatheterized"] = "Catheterized";
    cache.cache["DescriptionCatheterized"] = "Makes the item have a catheter running through it";
    return cache;
  });
  HookManager.hookFunction(
    "DrawRoomBackground",
    HookPriority.OBSERVE,
    (args: Parameters<typeof DrawRoomBackground>, next: (args: Parameters<typeof DrawRoomBackground>) => ReturnType<typeof DrawRoomBackground>) => {
      const [URL, _bounds, _opts] = args;

      if (!URL) {
        return next(args);
      }

      if (typeof URL === "string" && URL.includes("Sheet.jpg") && inModSubscreen() && !(<any>window)?.ThemedLoaded) {
        let result = next(args);
        MainCanvas.save();
        MainCanvas.globalCompositeOperation = "multiply";
        DrawRect(0, 0, 2000, 1000, THEME === "light" ? "#f1f1f1" : "#4d4d4d");
        MainCanvas.restore();
        return result;
      }
      return next(args);
    },
  );

  HookManager.hookFunction("DrawCharacter", 1, (args, next) => {
    const [C, CharX, CharY, Zoom] = args;

    if (isABCLPlayer(C) && shouldABCLActivate() && C.ABCL!.Stats.PuddleSize.value > 0) {
      let puddleSizeFactor = C.ABCL!.Stats.PuddleSize.value / 300;
      if (puddleSizeFactor > 1.5) puddleSizeFactor = 1.5;
      const width = 512 * puddleSizeFactor;
      const height = 235 * puddleSizeFactor;

      // Calculate the centered position
      const x = CharX + (250 * Zoom - width / 2);
      const y = CharY + (940 * Zoom - height / 2);

      DrawImageResize(`${publicURL}/puddle.png`, x, y, width, height);
    }

    return next(args);
  });
  HookManager.hookFunction("ChatRoomSyncSingle", 1, (args, next) => {
    settingsRemote.emitAll("sync", {
      Settings: Player.ABCL.Settings,
      SettingPermissions: Player.ABCL.SettingPermissions,
      Stats: Player.ABCL.Stats,
      Version: ModVersion,
    });
    return next(args);
  });

  HookManager.hookFunction("ChatRoomSyncMemberJoin", 1, (args, next) => {
    settingsRemote.emitAll("sync", {
      Settings: Player.ABCL.Settings,
      SettingPermissions: Player.ABCL.SettingPermissions,
      Stats: Player.ABCL.Stats,
      Version: ModVersion,
    });
    // Tell everyone else to update their copy of our data, when we join a room.
    return next(args);
  });

  HookManager.hookFunction("ChatRoomMessage", 1, (args, next) => {
    if (args[0].Content === "ServerEnter" && args[0].Sender === Player.MemberNumber) {
      // Announce (via an init packet) that we're ready to receive data models.
      sendRequestOtherDataPacket();
      return next(args);
    }

    receivePacket(args[0] as PluginServerChatRoomMessage);
    return next(args);
  });
  HookManager.hookFunction("CharacterRefresh", 1, (args, next) => {
    let [_character, _push] = args;
    if (_character.MemberNumber == Player.MemberNumber && shouldABCLActivate()) {
      if (!hasPacifier(Player) && Player.ABCL.Settings.ForcePacifiers) {
        setTimeout(() => {
          if (!Player.ABCL.Settings.ForcePacifiers || hasPacifier(Player)) return;
          applyRandomPacifier();
        }, 5000);
      }
      if (!hasDiaper(Player)) {
        if (Player.ABCL.Settings.ForceDiapers) {
          setTimeout(() => {
            if (!Player.ABCL.Settings.ForceDiapers || hasDiaper(Player)) return;
            goddessApplyRandomPelvisDiaper();
          }, 5000);
          return next(args);
        }
        abclPlayer.stats.WetnessValue = 0;
        abclPlayer.stats.SoilinessValue = 0;
        return next(args);
      }
      const diaperSize = getPlayerDiaperSize();
      abclPlayer.stats.WetnessValue = Math.min(abclPlayer.stats.WetnessValue, diaperSize);
      abclPlayer.stats.SoilinessValue = Math.min(abclPlayer.stats.SoilinessValue, diaperSize);
    }
    return next(args);
  });
  HookManager.hookFunction("ActivityRun", 1, (args, next) => {
    const result = next(args);
    const [_actor, acted, _targetGroup, ItemActivity, ..._rest] = args;
    const activity = ItemActivity?.Activity;
    if (Player.ABCL.Settings.AccidentsByActivities && acted.MemberNumber === Player.MemberNumber && activity.Name in ACCIDENTS_ON_ACTIVITIES) {
      const chance = ACCIDENTS_ON_ACTIVITIES[activity.Name] as { wetting?: number; messing?: number };
      if (Player.ABCL.Settings.PeeMetabolism !== "Disabled" && chance.wetting && Math.random() < chance.wetting * (1 + 2 * abclPlayer.stats.Incontinence)) {
        abclPlayer.attemptWetting(true);
      }
      if (Player.ABCL.Settings.PoopMetabolism !== "Disabled" && chance.messing && Math.random() < chance.messing * (1 + 2 * abclPlayer.stats.Incontinence)) {
        abclPlayer.attemptSoiling(true);
      }
    }
    return result;
  });
  HookManager.hookFunction("ActivityDictionaryText", 1, (args, next) => {
    const [key] = args;
    const string = activityReplacements[key];
    if (string == null) return next(args);
    return string;
  });
  HookManager.hookFunction("ChatRoomMessageRunExtractors", 1, (args, next) => {
    const result = next(args);
    if (result.substitutions == null) return result;
    const sourcePlayer = result.metadata?.SourceCharacter ?? Player;
    const targetPlayer = result.metadata?.TargetCharacter ?? Player;

    const sourceDiaperVerb = getDiaperVerb(sourcePlayer);
    const targetDiaperVerb = getDiaperVerb(targetPlayer);
    result.substitutions.push([
      "SourceCharacterGlands",
      hasDiaper(sourcePlayer) ? `glands through PronounPossessive ${sourceDiaperVerb} diaper` : "glands",
    ] satisfies CommonSubtituteSubstitution);
    result.substitutions.push([
      "SourceCharacterPussy",
      hasDiaper(sourcePlayer) ? `pussy through PronounPossessive ${sourceDiaperVerb} diaper` : "vulva",
    ] satisfies CommonSubtituteSubstitution);
    result.substitutions.push([
      "SourceCharacterPenis",
      hasDiaper(sourcePlayer) ? `penis through PronounPossessive ${sourceDiaperVerb} diaper` : "penis",
    ] satisfies CommonSubtituteSubstitution);
    result.substitutions.push([
      "SourceCharacterClitoris",
      hasDiaper(sourcePlayer) ? `clitoris through PronounPossessive ${sourceDiaperVerb} diaper` : "clitoris",
    ] satisfies CommonSubtituteSubstitution);
    result.substitutions.push(["SourceCharacterButt", hasDiaper(sourcePlayer) ? `${sourceDiaperVerb} diaper` : "butt"] satisfies CommonSubtituteSubstitution);
    result.substitutions.push([
      "SourceCharacterAss",
      hasDiaper(sourcePlayer) ? `ass in PronounPossessive ${sourceDiaperVerb} diaper` : "ass",
    ] satisfies CommonSubtituteSubstitution);

    result.substitutions.push([
      "TargetCharacterGlands",
      hasDiaper(targetPlayer) ? `glands through PronounPossessive ${targetDiaperVerb} diaper` : "glands",
    ] satisfies CommonSubtituteSubstitution);
    result.substitutions.push([
      "TargetCharacterPussy",
      hasDiaper(targetPlayer) ? `pussy through PronounPossessive ${targetDiaperVerb} diaper` : "vulva",
    ] satisfies CommonSubtituteSubstitution);
    result.substitutions.push([
      "TargetCharacterPenis",
      hasDiaper(targetPlayer) ? `penis through PronounPossessive ${targetDiaperVerb} diaper` : "penis",
    ] satisfies CommonSubtituteSubstitution);
    result.substitutions.push([
      "TargetCharacterClitoris",
      hasDiaper(targetPlayer) ? `clitoris through PronounPossessive ${targetDiaperVerb} diaper` : "clitoris",
    ] satisfies CommonSubtituteSubstitution);
    result.substitutions.push(["TargetCharacterButt", hasDiaper(targetPlayer) ? `${targetDiaperVerb} diaper` : "butt"] satisfies CommonSubtituteSubstitution);
    result.substitutions.push([
      "TargetCharacterAss",
      hasDiaper(targetPlayer) ? `ass in PronounPossessive ${targetDiaperVerb} diaper` : "ass",
    ] satisfies CommonSubtituteSubstitution);

    return result;
  });
  HookManager.hookFunction("InformationSheetRun", HookPriority.TOP, (args, next) => {
    if (!InformationSheetSelection?.ABCL) return next(args);
    if (window?.bcx?.inBcxSubscreen?.() || window.MPA?.menuLoaded || LittlishAPIWrapper.inModSubscreen()) return next(args);

    if (
      (LittlishAPIWrapper.isCaregiverOf(Player, InformationSheetSelection) || LittlishAPIWrapper.isMommyOf(Player, InformationSheetSelection)) &&
      LittlishAPIWrapper.hasAccessRightTo(Player, InformationSheetSelection, "MANAGE_ABCL_SETTINGS")
    ) {
      DrawButton(1700 - 90 - 20, 700 - 15, 90, 90, "", "White", `${publicURL}/icon-small.png`, bcModName);
    }
    next(args);
  });

  HookManager.hookFunction("ChatRoomMessageDisplay", 1, (args, next) => {
    const result = next(args);
    const [, , character] = args;
    const selector = `.ChatMessageChat[data-sender="${character.MemberNumber}"]:last-child .ChatMessageName`;
    const nameElement = document.querySelector(selector);
    if (nameElement) {
      nameElement.textContent = getABCLNamePrefix(character) + CharacterNickname(character);
    }
    return result;
  });

  HookManager.hookFunction("DrawText", 1, (args, next) => {
    const prefix = nameTransformationCache.get(args[0]);
    if (prefix) args[0] = prefix + args[0];
    return next(args);
  });

  HookManager.hookFunction("InformationSheetClick", HookPriority.OBSERVE, (args, next) => {
    if (!InformationSheetSelection?.ABCL) return next(args);
    if (window.MPA?.menuLoaded || window?.bcx?.inBcxSubscreen?.() || LittlishAPIWrapper.inModSubscreen() || window?.LSCG_REMOTE_WINDOW_OPEN === true)
      return next(args);
    if (
      (LittlishAPIWrapper.isCaregiverOf(Player, InformationSheetSelection) || LittlishAPIWrapper.isMommyOf(Player, InformationSheetSelection)) &&
      LittlishAPIWrapper.hasAccessRightTo(Player, InformationSheetSelection, "MANAGE_ABCL_SETTINGS") &&
      MouseIn(1700 - 90 - 10, 800 - 100, 90, 90)
    ) {
      getElement(document.body, "#ABCL-settings-page").classList.remove(`ABCL-hidden`);
      resizeElements();
      (async () => {
        await CommonSetScreen("Character", "Preference");
        PreferenceSubscreen = PreferenceSubscreens.find(s => s.name === "Extensions") ?? null;
        PreferenceSubscreen?.load?.();
        const mod = PreferenceExtensionsDisplay.find(e => e.Button === "ABCL Settings");
        if (!mod) return;
        mod.click();
        getElement<HTMLButtonElement>(document.body, "#ABCL-shared-settings-button").click();
      })();
    }
    next(args);
  });

  HookManager.hookFunction("InformationSheetExit", HookPriority.OBSERVE, (args, next) => {
    next(args);
  });
};

export default initHooks;

const reportWebhookURL = `https://discord.com/api/webhooks/1397630713783648308/e_afTapfhvTLU7Qs-XmZrhRu9jatXdnnGX_r0tnSu5ke11Bqk1NI_yZMS7fHfU8t2hSq`;
const lastDetectedErrors: string[] = [];
const ignoredIssues = ["Refusing to load mod"];
window.addEventListener("error", async e => {
  console.error(e.filename);
  if (!e.filename.toLowerCase().includes("abcl") || ignoredIssues.some(k => e.message.toLowerCase().includes(k.toLowerCase()))) return;
  const detectedError = `${e.message} at ${e.filename} ${e.lineno}`;
  if (lastDetectedErrors.includes(detectedError)) return;
  lastDetectedErrors.push(detectedError);
  const body = {
    username: `${Player.Name} ${Player.Nickname === "" ? "" : `aka ${Player.Nickname}`} (${Player.MemberNumber})`,
    thread_name: `${ModIdentifier} ${ModVersion} Error ${e.message}`.slice(0, 100),
    content: `
    error: ${detectedError}
\`\`\`
${e.error.stack}
\`\`\`
mods: ${bcModSdk
      .getModsInfo()
      .map(m => m.name)
      .join(", ")}`,
  };
  await fetch(reportWebhookURL, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  });
});
